using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using Microsoft.Win32;using BunjangAuto;using ExpResetTool;using Lumivolt.Admin;using Lumivolt.Security;
class ResetTests {
 static int pass,fail;static void Check(string name,bool ok){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)pass++;else fail++;}
 static void Reject(string name,Action a){try{a();Check(name,false);}catch{Check(name,true);}}
 static void Main(){AppDomain.CurrentDomain.AssemblyResolve+=delegate(object s,ResolveEventArgs e){using(var x=Assembly.GetExecutingAssembly().GetManifestResourceStream("lib."+new AssemblyName(e.Name).Name+".dll")){if(x==null)return null;using(var m=new MemoryStream()){x.CopyTo(m);return Assembly.Load(m.ToArray());}}};Environment.ExitCode=Run();}
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]static int Run(){string root=ResetEngine.DataRoot,vault=root+"-issuer";try{
  Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"photos"));File.WriteAllText(Path.Combine(root,"products.json"),"preserve products");File.WriteAllText(Path.Combine(root,"photos","image.jpg"),"preserve photo");File.WriteAllText(Path.Combine(root,"license.key"),"remove authentication");
  Reject("missing issuer refuses reset",()=>ResetEngine.Reset(vault,false));Check("unauthorized reset preserves client state",File.Exists(Path.Combine(root,"license.key")));
  IssuerService.Create(vault);Reject("untrusted issuer refuses reset",()=>ResetEngine.Reset(vault,false));var pub=IssuerService.Load(vault).GeneratePublicKey().GetEncoded();TrustedKeys.All.Add(LicenseProtocol.KeyId(pub),pub);
  Reject("path escape rejected",()=>ResetEngine.SafeTree(vault,root));
  Directory.CreateDirectory(Path.Combine(vault,"records"));File.WriteAllText(Path.Combine(vault,"records","a.lvlicense"),"history");Directory.CreateDirectory(Path.Combine(vault,"credits"));File.WriteAllText(Path.Combine(vault,"credits","credit"),"credit history");
  using(var k=Registry.CurrentUser.CreateSubKey(ResetEngine.UsageRegistry))k.SetValue("State",new byte[]{1});foreach(var name in ResetEngine.DeviceKeys)using(var k=CngKey.Create(CngAlgorithm.ECDsaP256,name,new CngKeyCreationParameters{Provider=ResetEngine.KeyProvider})){}
  using(var held=new FileStream(Path.Combine(root,"license.key"),FileMode.Open,FileAccess.Read,FileShare.Read))Reject("locked files fail before deletion",()=>ResetEngine.Reset(vault,false));Check("failed preflight preserves license",File.Exists(Path.Combine(root,"license.key")));
  var result=ResetEngine.Reset(vault,false);Check("authorized reset succeeds",(bool)result["success"]);Check("products preserved",File.ReadAllText(Path.Combine(root,"products.json"))=="preserve products");Check("photos preserved",File.ReadAllText(Path.Combine(root,"photos","image.jpg"))=="preserve photo");Check("license removed",!File.Exists(Path.Combine(root,"license.key")));using(var k=Registry.CurrentUser.OpenSubKey(ResetEngine.UsageRegistry))Check("registry removed",k==null);foreach(var name in ResetEngine.DeviceKeys)Check("device key removed",!CngKey.Exists(name,ResetEngine.KeyProvider));Check("issuer key preserved",IssuerService.Load(vault)!=null);Check("master history default preserved",Directory.Exists(Path.Combine(vault,"records"))&&Directory.Exists(Path.Combine(vault,"credits")));
  ResetEngine.Reset(vault,true);Check("optional master history removed",!Directory.Exists(Path.Combine(vault,"records"))&&!Directory.Exists(Path.Combine(vault,"credits")));Check("repeat reset safe",(bool)ResetEngine.Reset(vault,true)["success"]);
 }catch(Exception e){Console.WriteLine(e);fail++;}finally{foreach(var name in ResetEngine.DeviceKeys)if(CngKey.Exists(name,ResetEngine.KeyProvider))using(var k=CngKey.Open(name,ResetEngine.KeyProvider))k.Delete();Registry.CurrentUser.DeleteSubKeyTree(ResetEngine.UsageRegistry,false);Registry.CurrentUser.DeleteSubKeyTree(ResetEngine.IssuerRegistry,false);}
 Console.WriteLine("RESET: "+pass+" passed, "+fail+" failed");return fail==0?0:1;}
}
